-- =====================================================================================
-- AI Watch Spaces — target database design, v0.4 (M0.2 documentation correction, 2026-10-26)
-- Status: APPROVED by the user on 2026-10-26 (v0.4). M1 authorized; later milestones need explicit authorization.
-- PostgreSQL 17 + Flyway. IDs are UUIDs generated by the Java application.
--
-- THIS FILE IS THE TARGET-STATE DESIGN, NOT A MIGRATION.
-- Flyway migrations are written per feature slice (see "Migration slicing" at the end) and
-- must, once all slices are applied, produce exactly this schema. Any deviation must be
-- recorded in SYSTEM_DESIGN.md before the migration is written.
--
-- Conventions
--   * Enumerations: VARCHAR + CHECK (UPPER_SNAKE). No PostgreSQL ENUM types (easier evolution).
--   * Time: TIMESTAMPTZ in UTC. Playback/timeline positions: INTEGER milliseconds.
--   * Deletion: ON DELETE RESTRICT everywhere. Domain rows are never hard-deleted in normal
--     operation; lifecycle columns (status, left_at, revoked_at, unpinned_at ...) are used instead.
--   * Composite foreign keys enforce "belongs to the same title / timeline version / room"
--     relationships in the database (audit finding I6). Composite FKs use the default
--     MATCH SIMPLE: when any referencing column is NULL the FK is not checked, which is the
--     intended behaviour for optional references.
--   * updated_at columns are maintained by the application in the same transaction.
--   * Room-scoped timestamps are written from the lane's single canonical mutationInstant
--     (Java Clock read once per mutation, truncated to microseconds, never earlier than the
--     room's previous instant). room_events.occurred_at deliberately has NO database default.
-- =====================================================================================


-- -------------------------------------------------------------------------------------
-- Identity and authentication (modules: users, auth)
-- -------------------------------------------------------------------------------------

CREATE TABLE app_users (
    id UUID PRIMARY KEY,
    email VARCHAR(320) NOT NULL,
    normalized_email VARCHAR(320) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,              -- DelegatingPasswordEncoder format, e.g. "{bcrypt}$2a$12$..."
    display_name VARCHAR(80) NOT NULL,
    system_role VARCHAR(16) NOT NULL DEFAULT 'USER'
        CHECK (system_role IN ('USER', 'ADMIN')),     -- global role only; HOST/VIEWER are room-scoped
    subtitle_locale VARCHAR(16) NOT NULL DEFAULT 'en', -- BCP 47 tag, validated by the application
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Opaque refresh tokens. Only SHA-256 hex hashes are stored.
-- Rotation: every successful refresh revokes the presented token (ROTATED), links it to its
-- replacement, and issues a new token in the same family. Presenting an already revoked
-- token is a replay: the whole family is revoked (REUSE_DETECTED) and the request fails.
CREATE TABLE refresh_tokens (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    family_id UUID NOT NULL,
    token_hash CHAR(64) NOT NULL UNIQUE,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at TIMESTAMPTZ,
    revoked_reason VARCHAR(24)
        CHECK (revoked_reason IN ('ROTATED', 'LOGOUT', 'REUSE_DETECTED')),
    replaced_by_token_id UUID REFERENCES refresh_tokens(id) ON DELETE RESTRICT,
    CHECK (expires_at > created_at),
    CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL)),
    CHECK (replaced_by_token_id IS NULL OR revoked_reason = 'ROTATED')
);
CREATE INDEX ix_refresh_tokens_user_expiry ON refresh_tokens(user_id, expires_at);
CREATE INDEX ix_refresh_tokens_family ON refresh_tokens(family_id);


-- -------------------------------------------------------------------------------------
-- Catalogue (module: catalog)
-- -------------------------------------------------------------------------------------

CREATE TABLE titles (
    id UUID PRIMARY KEY,
    slug VARCHAR(160) NOT NULL UNIQUE,
    name VARCHAR(200) NOT NULL,
    description TEXT,
    duration_ms INTEGER NOT NULL CHECK (duration_ms > 0),
    video_asset_uri TEXT NOT NULL,
    default_locale VARCHAR(16) NOT NULL DEFAULT 'en',  -- base subtitle locale for cue-key validation and fallback
    status VARCHAR(16) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'PUBLISHED', 'ARCHIVED')),
    created_by UUID REFERENCES app_users(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ix_titles_status_name ON titles(status, name);

CREATE TABLE genres (
    id UUID PRIMARY KEY,
    name VARCHAR(80) NOT NULL UNIQUE                   -- stored normalized (trimmed, lower-case)
);

CREATE TABLE title_genres (
    title_id UUID NOT NULL REFERENCES titles(id) ON DELETE RESTRICT,
    genre_id UUID NOT NULL REFERENCES genres(id) ON DELETE RESTRICT,
    PRIMARY KEY (title_id, genre_id)
);
CREATE INDEX ix_title_genres_genre ON title_genres(genre_id, title_id);


-- -------------------------------------------------------------------------------------
-- Timeline metadata (module: timeline)
-- -------------------------------------------------------------------------------------

-- Lifecycle (status):            DRAFT -> CURRENT -> SUPERSEDED
-- Validation (validation_status): PENDING -> VALID | INVALID   (re-validation allowed while DRAFT)
-- timeline_events / variation_options rows are materialized ONLY for VALID versions, and a
-- version's events are immutable once materialized (retrieval caches rely on this).
CREATE TABLE title_timeline_versions (
    id UUID PRIMARY KEY,
    title_id UUID NOT NULL REFERENCES titles(id) ON DELETE RESTRICT,
    version_number INTEGER NOT NULL CHECK (version_number > 0),
    status VARCHAR(16) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'CURRENT', 'SUPERSEDED')),
    source_format VARCHAR(8) NOT NULL CHECK (source_format IN ('JSON', 'YAML')),
    raw_document TEXT NOT NULL CHECK (octet_length(raw_document) <= 2097152),  -- 2 MiB upload limit
    schema_version INTEGER,                            -- NULL only if the document could not be parsed
    content_hash CHAR(64) NOT NULL,                    -- SHA-256 of raw_document
    validation_status VARCHAR(16) NOT NULL DEFAULT 'PENDING'
        CHECK (validation_status IN ('PENDING', 'VALID', 'INVALID')),
    validation_errors JSONB NOT NULL DEFAULT '[]'::jsonb,   -- [{path, code, message}]
    validated_at TIMESTAMPTZ,
    uploaded_by UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at TIMESTAMPTZ,
    UNIQUE (title_id, version_number),
    UNIQUE (title_id, id),
    CHECK ((validation_status = 'PENDING') = (validated_at IS NULL)),
    CHECK (validation_status <> 'INVALID' OR jsonb_array_length(validation_errors) > 0),
    CHECK (validation_status <> 'VALID' OR jsonb_array_length(validation_errors) = 0),
    CHECK (status = 'DRAFT' OR validation_status = 'VALID'),
    CHECK ((status = 'DRAFT') = (published_at IS NULL))
);
CREATE UNIQUE INDEX ux_timeline_one_current_per_title
    ON title_timeline_versions(title_id) WHERE status = 'CURRENT';

CREATE TABLE timeline_events (
    id UUID PRIMARY KEY,
    timeline_version_id UUID NOT NULL REFERENCES title_timeline_versions(id) ON DELETE RESTRICT,
    event_key VARCHAR(160) NOT NULL,                   -- stable author key; distinct from the DB id
    event_type VARCHAR(32) NOT NULL
        CHECK (event_type IN ('SCENE', 'CHARACTER', 'TRIVIA', 'GLOSSARY', 'VARIATION_POINT')),
    start_ms INTEGER NOT NULL CHECK (start_ms >= 0),
    end_ms INTEGER,                                    -- NULL = point event
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,        -- type-specific fields, plain text only
    search_text TEXT NOT NULL DEFAULT '',              -- normalized text used for keyword retrieval
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (end_ms IS NULL OR end_ms >= start_ms),
    UNIQUE (timeline_version_id, event_key),
    UNIQUE (timeline_version_id, id)
);
-- start/end inside title duration is validated by the application (cross-table rule).
CREATE INDEX ix_timeline_events_version_start
    ON timeline_events(timeline_version_id, start_ms);
CREATE INDEX ix_timeline_events_version_type_start
    ON timeline_events(timeline_version_id, event_type, start_ms);


-- -------------------------------------------------------------------------------------
-- Subtitles (module: variations). MVP: tracks and cues are seeded, not uploaded via API.
-- -------------------------------------------------------------------------------------

CREATE TABLE subtitle_tracks (
    id UUID PRIMARY KEY,
    title_id UUID NOT NULL REFERENCES titles(id) ON DELETE RESTRICT,
    locale VARCHAR(16) NOT NULL,
    version_number INTEGER NOT NULL CHECK (version_number > 0),
    asset_uri TEXT NOT NULL,
    checksum CHAR(64),                                 -- SHA-256 of the asset file
    status VARCHAR(16) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'APPROVED', 'ACTIVE', 'ARCHIVED')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (title_id, locale, version_number),
    UNIQUE (id, title_id, locale),                     -- composite FK target for room pinning
    UNIQUE (id, locale)                                -- composite FK target for SUBTITLE_TRACK_SWAP options (v0.4)
);
CREATE UNIQUE INDEX ux_subtitle_one_active_per_locale
    ON subtitle_tracks(title_id, locale) WHERE status = 'ACTIVE';

-- cue_key is stable across track versions and locales of the same title; variation points
-- reference cues by cue_key (payload.cueKey), never by a track-specific cue id.
CREATE TABLE subtitle_cues (
    id UUID PRIMARY KEY,
    subtitle_track_id UUID NOT NULL REFERENCES subtitle_tracks(id) ON DELETE RESTRICT,
    cue_key VARCHAR(160) NOT NULL,
    start_ms INTEGER NOT NULL CHECK (start_ms >= 0),
    end_ms INTEGER NOT NULL CHECK (end_ms > start_ms),
    text_value TEXT NOT NULL,
    UNIQUE (subtitle_track_id, cue_key)
);
CREATE INDEX ix_subtitle_cues_track_start ON subtitle_cues(subtitle_track_id, start_ms);


-- -------------------------------------------------------------------------------------
-- Pre-authored, pre-approved variation options (modules: timeline writes, variations reads)
-- -------------------------------------------------------------------------------------

CREATE TABLE variation_options (
    id UUID PRIMARY KEY,
    timeline_event_id UUID NOT NULL REFERENCES timeline_events(id) ON DELETE RESTRICT,
    option_key VARCHAR(100) NOT NULL,
    label VARCHAR(200) NOT NULL,
    option_type VARCHAR(32) NOT NULL
        CHECK (option_type IN ('SUBTITLE_TEXT', 'SUBTITLE_TRACK_SWAP', 'ASSET_SWAP', 'NARRATIVE_BRANCH')),
    locale VARCHAR(16),
    text_value TEXT,
    asset_uri TEXT,
    subtitle_track_id UUID,                            -- only for SUBTITLE_TRACK_SWAP; FK below
    is_default BOOLEAN NOT NULL DEFAULT FALSE,
    is_approved BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    UNIQUE (timeline_event_id, option_key),
    UNIQUE (timeline_event_id, id),                    -- composite FK target (votes, ballots, applications)
    CHECK (option_type <> 'SUBTITLE_TEXT'       OR (text_value IS NOT NULL AND locale IS NOT NULL)),
    CHECK (option_type <> 'SUBTITLE_TRACK_SWAP' OR (subtitle_track_id IS NOT NULL AND locale IS NOT NULL)),
    -- A swap option's locale must equal its track's locale (v0.4). Same-title rule: R11.
    FOREIGN KEY (subtitle_track_id, locale) REFERENCES subtitle_tracks(id, locale) ON DELETE RESTRICT,
    CHECK (option_type NOT IN ('ASSET_SWAP', 'NARRATIVE_BRANCH') OR asset_uri IS NOT NULL)
);
CREATE UNIQUE INDEX ux_variation_single_default
    ON variation_options(timeline_event_id) WHERE is_default = TRUE;
CREATE INDEX ix_variation_options_event_approved
    ON variation_options(timeline_event_id, is_approved, sort_order);


-- -------------------------------------------------------------------------------------
-- Watch Spaces, membership and moderation (module: watchspace)
-- -------------------------------------------------------------------------------------

-- host_user_id is the ONLY source of truth for who hosts the room (finding I7).
-- last_sequence_no / state_version are advanced only by the room mutation lane, with an
-- optimistic guard (UPDATE ... WHERE last_sequence_no = :expected). No MAX(sequence_no)+1.
CREATE TABLE watch_spaces (
    id UUID PRIMARY KEY,
    title_id UUID NOT NULL REFERENCES titles(id) ON DELETE RESTRICT,
    host_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    name VARCHAR(120) NOT NULL,
    privacy VARCHAR(20) NOT NULL DEFAULT 'INVITE_ONLY'
        CHECK (privacy IN ('PUBLIC_LINK', 'INVITE_ONLY')),
    invite_code_hash CHAR(64) NOT NULL UNIQUE,         -- HMAC-SHA256(INVITE_CODE_PEPPER, normalized code), hex
    invite_code_rotated_at TIMESTAMPTZ,
    status VARCHAR(24) NOT NULL DEFAULT 'SCHEDULED'
        CHECK (status IN ('SCHEDULED', 'LIVE', 'HOST_DISCONNECTED', 'ENDED')),
    ended_reason VARCHAR(24)
        CHECK (ended_reason IN ('HOST_ENDED', 'IDLE_TIMEOUT', 'UNSTARTED_EXPIRED')),
    playback_state VARCHAR(16) NOT NULL DEFAULT 'PAUSED'
        CHECK (playback_state IN ('PLAYING', 'PAUSED', 'BUFFERING')),  -- SEEKING is never persisted
    max_participants INTEGER NOT NULL DEFAULT 25 CHECK (max_participants BETWEEN 2 AND 50),
    ai_verbosity VARCHAR(16) NOT NULL DEFAULT 'NORMAL'
        CHECK (ai_verbosity IN ('MINIMAL', 'NORMAL', 'CHATTY')),       -- AI answer style/length only
    trivia_enabled BOOLEAN NOT NULL DEFAULT TRUE,                       -- proactive trivia only
    voting_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    is_locked BOOLEAN NOT NULL DEFAULT FALSE,
    chat_muted BOOLEAN NOT NULL DEFAULT FALSE,                          -- room-wide chat mute
    scheduled_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at TIMESTAMPTZ,
    ended_at TIMESTAMPTZ,
    host_disconnected_at TIMESTAMPTZ,
    session_correlation_id UUID UNIQUE,                -- assigned at start; tags every log line of the session
    pinned_timeline_version_id UUID,                   -- assigned at start; never changes afterwards
    last_playback_position_ms INTEGER NOT NULL DEFAULT 0 CHECK (last_playback_position_ms >= 0),
    playback_updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    state_version BIGINT NOT NULL DEFAULT 0 CHECK (state_version >= 0),
    last_sequence_no BIGINT NOT NULL DEFAULT 0 CHECK (last_sequence_no >= 0),
    UNIQUE (id, title_id),                             -- composite FK target
    UNIQUE (id, pinned_timeline_version_id),           -- composite FK target: "uses this room's pinned version"
    FOREIGN KEY (title_id, pinned_timeline_version_id)
        REFERENCES title_timeline_versions(title_id, id) ON DELETE RESTRICT,
    CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at >= started_at),
    CHECK ((status = 'ENDED') = (ended_at IS NOT NULL)),
    CHECK ((status = 'ENDED') = (ended_reason IS NOT NULL)),
    CHECK (status NOT IN ('LIVE', 'HOST_DISCONNECTED') OR started_at IS NOT NULL),
    CHECK (status <> 'HOST_DISCONNECTED' OR host_disconnected_at IS NOT NULL),
    CHECK (started_at IS NULL OR session_correlation_id IS NOT NULL)
);
CREATE INDEX ix_watch_spaces_host_status ON watch_spaces(host_user_id, status, created_at DESC);
CREATE INDEX ix_watch_spaces_title_status ON watch_spaces(title_id, status);
CREATE INDEX ix_watch_spaces_scheduled ON watch_spaces(status, scheduled_at);

-- Subtitle tracks pinned for the room session (one per locale with an ACTIVE track at start).
CREATE TABLE room_subtitle_tracks (
    watch_space_id UUID NOT NULL,
    title_id UUID NOT NULL,
    locale VARCHAR(16) NOT NULL,
    subtitle_track_id UUID NOT NULL,
    pinned_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (watch_space_id, locale),
    FOREIGN KEY (watch_space_id, title_id)
        REFERENCES watch_spaces(id, title_id) ON DELETE RESTRICT,
    FOREIGN KEY (subtitle_track_id, title_id, locale)
        REFERENCES subtitle_tracks(id, title_id, locale) ON DELETE RESTRICT
);

-- One row per membership interval (join .. leave). Room role is NOT stored here:
-- effective role = HOST iff user_id = watch_spaces.host_user_id, else VIEWER.
CREATE TABLE watch_space_participants (
    id UUID PRIMARY KEY,
    watch_space_id UUID NOT NULL REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),   -- updated on connect/disconnect only, never per heartbeat
    left_at TIMESTAMPTZ,
    leave_reason VARCHAR(24)
        CHECK (leave_reason IN ('LEFT', 'REMOVED', 'GRACE_EXPIRED', 'ROOM_ENDED')),
    CHECK (left_at IS NULL OR left_at >= joined_at),
    CHECK ((left_at IS NULL) = (leave_reason IS NULL))
);
CREATE UNIQUE INDEX ux_active_room_membership
    ON watch_space_participants(watch_space_id, user_id)
    WHERE left_at IS NULL;
CREATE INDEX ix_room_participants_room_joined
    ON watch_space_participants(watch_space_id, joined_at);
CREATE INDEX ix_room_participants_user_joined
    ON watch_space_participants(user_id, joined_at DESC);

-- Per-room, per-user moderation state that survives leave/rejoin and reconnects (finding I10).
-- A user with removed_at set can never rejoin this room.
CREATE TABLE watch_space_moderation (
    watch_space_id UUID NOT NULL REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    is_muted BOOLEAN NOT NULL DEFAULT FALSE,
    muted_at TIMESTAMPTZ,
    muted_by UUID REFERENCES app_users(id) ON DELETE RESTRICT,
    removed_at TIMESTAMPTZ,
    removed_by UUID REFERENCES app_users(id) ON DELETE RESTRICT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (watch_space_id, user_id),
    CHECK (NOT is_muted OR (muted_at IS NOT NULL AND muted_by IS NOT NULL)),
    CHECK ((removed_at IS NULL) = (removed_by IS NULL))
);


-- -------------------------------------------------------------------------------------
-- Room event ledger (module: watchspace owns writes; other modules append through its API)
-- -------------------------------------------------------------------------------------

-- The event-type catalog is closed (finding I11). Adding a type requires a design change,
-- a Flyway migration of this CHECK, and an analytics-reconciliation test update.
-- Ephemeral traffic (sync ping/report, typing, reactions, presence quality) is never stored.
CREATE TABLE room_events (
    id UUID PRIMARY KEY,
    watch_space_id UUID NOT NULL REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    sequence_no BIGINT NOT NULL CHECK (sequence_no > 0),
    actor_user_id UUID REFERENCES app_users(id) ON DELETE RESTRICT,   -- NULL for system actions
    event_type VARCHAR(64) NOT NULL CHECK (event_type IN (
        'ROOM_CREATED', 'ROOM_STARTED', 'ROOM_ENDED', 'ROOM_SETTINGS_UPDATED',
        'ROOM_LOCK_CHANGED', 'INVITE_CODE_ROTATED', 'RUNTIME_RECOVERED',
        'PARTICIPANT_JOINED', 'PARTICIPANT_LEFT', 'PARTICIPANT_REMOVED', 'PARTICIPANT_MUTE_CHANGED',
        'HOST_DISCONNECTED', 'HOST_RECONNECTED', 'HOST_TRANSFERRED', 'HOST_PROMOTED',
        'PLAYBACK_PLAY', 'PLAYBACK_PAUSE', 'PLAYBACK_SEEK',
        'PLAYBACK_BUFFERING_STARTED', 'PLAYBACK_BUFFERING_ENDED',
        'CHAT_MESSAGE_POSTED',
        'AI_QUESTION_CREATED', 'AI_ANSWER_PUBLISHED', 'AI_FACT_PINNED', 'AI_FACT_UNPINNED',
        'TRIVIA_SURFACED',
        'VOTE_OPENED', 'VOTE_CLOSED', 'VOTE_CANCELLED', 'VARIATION_APPLIED'
    )),
    playback_position_ms INTEGER CHECK (playback_position_ms IS NULL OR playback_position_ms >= 0),
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,        -- references only; never duplicates chat bodies
    idempotency_key VARCHAR(200),                      -- e.g. "cmd:<userId>:<requestId>", "trivia:<timelineEventId>"
    correlation_id UUID,                               -- request/command correlation id
    occurred_at TIMESTAMPTZ NOT NULL,                  -- the mutation's canonical instant; no DB default (v0.3)
    UNIQUE (watch_space_id, sequence_no)
);
CREATE UNIQUE INDEX ux_room_event_idempotency
    ON room_events(watch_space_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
-- At most one creation/start/end event per room, so analytics boundaries are unambiguous (v0.3).
CREATE UNIQUE INDEX ux_room_event_lifecycle_once
    ON room_events(watch_space_id, event_type)
    WHERE event_type IN ('ROOM_CREATED', 'ROOM_STARTED', 'ROOM_ENDED');
CREATE INDEX ix_room_events_type_time
    ON room_events(watch_space_id, event_type, occurred_at);


-- -------------------------------------------------------------------------------------
-- AI Q&A, citations and pinned facts (module: ai)
-- -------------------------------------------------------------------------------------

CREATE TABLE ai_questions (
    id UUID PRIMARY KEY,
    watch_space_id UUID NOT NULL REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,  -- from the JWT, never the request body
    title_id UUID NOT NULL REFERENCES titles(id) ON DELETE RESTRICT,
    timeline_version_id UUID NOT NULL,
    client_request_id VARCHAR(100),                    -- deduplicates retries per room+user
    playback_position_ms INTEGER NOT NULL CHECK (playback_position_ms >= 0),   -- authoritative server position
    client_reported_position_ms INTEGER
        CHECK (client_reported_position_ms IS NULL OR client_reported_position_ms >= 0),  -- advisory/diagnostic only
    question TEXT NOT NULL CHECK (char_length(question) BETWEEN 1 AND 500),
    verbosity VARCHAR(16) NOT NULL CHECK (verbosity IN ('MINIMAL', 'NORMAL', 'CHATTY')),
    answer TEXT CHECK (answer IS NULL OR char_length(answer) <= 2000),
    status VARCHAR(24) NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING', 'ANSWERED', 'INSUFFICIENT_CONTEXT', 'FAILED')),
    failure_reason VARCHAR(32)
        CHECK (failure_reason IN ('TIMEOUT', 'PROVIDER_ERROR', 'INVALID_MODEL_OUTPUT', 'CAPACITY')),
    provider VARCHAR(80),
    model VARCHAR(120),
    latency_ms INTEGER CHECK (latency_ms IS NULL OR latency_ms >= 0),
    provider_latency_ms INTEGER CHECK (provider_latency_ms IS NULL OR provider_latency_ms >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    answered_at TIMESTAMPTZ,
    UNIQUE (id, timeline_version_id),
    UNIQUE (id, watch_space_id),
    FOREIGN KEY (watch_space_id, title_id)
        REFERENCES watch_spaces(id, title_id) ON DELETE RESTRICT,
    FOREIGN KEY (title_id, timeline_version_id)
        REFERENCES title_timeline_versions(title_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (watch_space_id, timeline_version_id)
        REFERENCES watch_spaces(id, pinned_timeline_version_id) ON DELETE RESTRICT,
    CHECK ((status = 'FAILED') = (failure_reason IS NOT NULL)),
    CHECK (status = 'PENDING' OR answered_at IS NOT NULL)
);
CREATE UNIQUE INDEX ux_ai_questions_client_request
    ON ai_questions(watch_space_id, user_id, client_request_id) WHERE client_request_id IS NOT NULL;
CREATE INDEX ix_ai_questions_room_time ON ai_questions(watch_space_id, created_at DESC);
CREATE INDEX ix_ai_questions_user_time ON ai_questions(user_id, created_at DESC);

-- Every cited source must be an event of the timeline version used for retrieval.
CREATE TABLE ai_answer_sources (
    question_id UUID NOT NULL,
    timeline_version_id UUID NOT NULL,
    timeline_event_id UUID NOT NULL,
    relevance_rank INTEGER NOT NULL CHECK (relevance_rank > 0),
    explanation VARCHAR(300),                          -- model's short "why this entry" note, validated
    evidence_excerpt VARCHAR(500),                     -- server-built excerpt of the authored metadata
    PRIMARY KEY (question_id, timeline_event_id),
    UNIQUE (question_id, relevance_rank),
    FOREIGN KEY (question_id, timeline_version_id)
        REFERENCES ai_questions(id, timeline_version_id) ON DELETE RESTRICT,
    FOREIGN KEY (timeline_version_id, timeline_event_id)
        REFERENCES timeline_events(timeline_version_id, id) ON DELETE RESTRICT
);

-- Host-pinned fact: either an ANSWERED AI answer from this room or a TRIVIA event from the
-- room's pinned timeline version. At most one active pin per room (a new pin replaces it).
CREATE TABLE ai_pinned_facts (
    id UUID PRIMARY KEY,
    watch_space_id UUID NOT NULL REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    pin_type VARCHAR(16) NOT NULL CHECK (pin_type IN ('AI_ANSWER', 'TRIVIA')),
    ai_question_id UUID,
    timeline_version_id UUID,
    timeline_event_id UUID,
    pinned_by UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    pinned_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    unpinned_at TIMESTAMPTZ,
    unpinned_by UUID REFERENCES app_users(id) ON DELETE RESTRICT,
    FOREIGN KEY (ai_question_id, watch_space_id)
        REFERENCES ai_questions(id, watch_space_id) ON DELETE RESTRICT,
    FOREIGN KEY (watch_space_id, timeline_version_id)
        REFERENCES watch_spaces(id, pinned_timeline_version_id) ON DELETE RESTRICT,
    FOREIGN KEY (timeline_version_id, timeline_event_id)
        REFERENCES timeline_events(timeline_version_id, id) ON DELETE RESTRICT,
    CHECK (
        (pin_type = 'AI_ANSWER' AND ai_question_id IS NOT NULL
             AND timeline_event_id IS NULL AND timeline_version_id IS NULL)
     OR (pin_type = 'TRIVIA' AND ai_question_id IS NULL
             AND timeline_event_id IS NOT NULL AND timeline_version_id IS NOT NULL)
    ),
    CHECK ((unpinned_at IS NULL) = (unpinned_by IS NULL)),
    CHECK (unpinned_at IS NULL OR unpinned_at >= pinned_at)
);
CREATE UNIQUE INDEX ux_ai_pinned_one_active_per_room
    ON ai_pinned_facts(watch_space_id) WHERE unpinned_at IS NULL;


-- -------------------------------------------------------------------------------------
-- Chat history (module: chat). Written in the same transaction as its ledger event.
-- -------------------------------------------------------------------------------------

CREATE TABLE chat_messages (
    id UUID PRIMARY KEY,
    room_event_id UUID NOT NULL UNIQUE REFERENCES room_events(id) ON DELETE RESTRICT,
    user_id UUID REFERENCES app_users(id) ON DELETE RESTRICT,           -- NULL for AI/system
    message_type VARCHAR(16) NOT NULL
        CHECK (message_type IN ('CHAT', 'AI_QUESTION', 'AI_ANSWER', 'SYSTEM')),
    body TEXT NOT NULL CHECK (char_length(body) BETWEEN 1 AND 2000),   -- plain text; policy in SYSTEM_DESIGN §8.3
    playback_position_ms INTEGER CHECK (playback_position_ms IS NULL OR playback_position_ms >= 0),
    ai_question_id UUID REFERENCES ai_questions(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (message_type NOT IN ('AI_QUESTION', 'AI_ANSWER') OR ai_question_id IS NOT NULL),
    CHECK (message_type <> 'CHAT' OR user_id IS NOT NULL)
);
CREATE INDEX ix_chat_messages_ai_question ON chat_messages(ai_question_id);


-- -------------------------------------------------------------------------------------
-- Votes and applied variations (module: variations)
-- -------------------------------------------------------------------------------------

-- Lifecycle: OPEN -> APPLIED (tallied; winner recorded and application row written)
--            OPEN -> CANCELLED (seek past point, host cancel, room ended, recovery)
CREATE TABLE room_votes (
    id UUID PRIMARY KEY,
    watch_space_id UUID NOT NULL REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    timeline_version_id UUID NOT NULL,
    timeline_event_id UUID NOT NULL,
    opened_by UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    status VARCHAR(16) NOT NULL DEFAULT 'OPEN'
        CHECK (status IN ('OPEN', 'APPLIED', 'CANCELLED')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    closes_at TIMESTAMPTZ NOT NULL,
    closed_at TIMESTAMPTZ,
    close_reason VARCHAR(24) CHECK (close_reason IN ('TIMER', 'MARKER_REACHED')),
    cancel_reason VARCHAR(24)
        CHECK (cancel_reason IN ('SEEK_PASSED', 'HOST_CANCELLED', 'ROOM_ENDED', 'RECOVERY_POINT_PASSED')),
    winning_option_id UUID,
    UNIQUE (id, timeline_event_id),
    UNIQUE (id, timeline_event_id, winning_option_id),
    FOREIGN KEY (watch_space_id, timeline_version_id)
        REFERENCES watch_spaces(id, pinned_timeline_version_id) ON DELETE RESTRICT,
    FOREIGN KEY (timeline_version_id, timeline_event_id)
        REFERENCES timeline_events(timeline_version_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (timeline_event_id, winning_option_id)
        REFERENCES variation_options(timeline_event_id, id) ON DELETE RESTRICT,
    CHECK (closes_at > created_at),
    CHECK (status <> 'OPEN' OR (closed_at IS NULL AND winning_option_id IS NULL
                                AND close_reason IS NULL AND cancel_reason IS NULL)),
    CHECK (status <> 'APPLIED' OR (closed_at IS NOT NULL AND winning_option_id IS NOT NULL
                                   AND close_reason IS NOT NULL AND cancel_reason IS NULL)),
    CHECK (status <> 'CANCELLED' OR (closed_at IS NOT NULL AND winning_option_id IS NULL
                                     AND cancel_reason IS NOT NULL AND close_reason IS NULL))
);
CREATE UNIQUE INDEX ux_one_open_vote_per_room_event
    ON room_votes(watch_space_id, timeline_event_id) WHERE status = 'OPEN';
CREATE INDEX ix_room_votes_room_status_close ON room_votes(watch_space_id, status, closes_at);

-- One effective ballot per user per vote; re-voting replaces the row until the vote closes.
CREATE TABLE variation_votes (
    vote_id UUID NOT NULL,
    timeline_event_id UUID NOT NULL,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    option_id UUID NOT NULL,
    cast_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (vote_id, user_id),
    FOREIGN KEY (vote_id, timeline_event_id)
        REFERENCES room_votes(id, timeline_event_id) ON DELETE RESTRICT,
    FOREIGN KEY (timeline_event_id, option_id)
        REFERENCES variation_options(timeline_event_id, id) ON DELETE RESTRICT
);
CREATE INDEX ix_variation_votes_tally ON variation_votes(vote_id, option_id);

-- The variation actually applied in a room: one per variation point per room session.
-- Source VOTE must equal the vote's recorded winner; HOST_SELECTION is a host choice among
-- existing approved options. Applied variations stay applied if the host later seeks backward.
CREATE TABLE room_variation_applications (
    id UUID PRIMARY KEY,
    watch_space_id UUID NOT NULL REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    timeline_version_id UUID NOT NULL,
    timeline_event_id UUID NOT NULL,
    option_id UUID NOT NULL,
    source VARCHAR(16) NOT NULL CHECK (source IN ('VOTE', 'HOST_SELECTION')),
    room_vote_id UUID,
    applied_by UUID REFERENCES app_users(id) ON DELETE RESTRICT,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (watch_space_id, timeline_event_id),
    FOREIGN KEY (watch_space_id, timeline_version_id)
        REFERENCES watch_spaces(id, pinned_timeline_version_id) ON DELETE RESTRICT,
    FOREIGN KEY (timeline_version_id, timeline_event_id)
        REFERENCES timeline_events(timeline_version_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (timeline_event_id, option_id)
        REFERENCES variation_options(timeline_event_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (room_vote_id, timeline_event_id, option_id)
        REFERENCES room_votes(id, timeline_event_id, winning_option_id) ON DELETE RESTRICT,
    CHECK ((source = 'VOTE') = (room_vote_id IS NOT NULL)),
    CHECK (source <> 'HOST_SELECTION' OR applied_by IS NOT NULL)
);


-- -------------------------------------------------------------------------------------
-- Recommendation inputs (module: recommendations)
-- -------------------------------------------------------------------------------------

-- Room-derived watch facts only; never written directly by clients (finding C6/I13).
-- Recomputed from the room ledger at the user's final leave and finalized at room end.
CREATE TABLE title_interactions (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    title_id UUID NOT NULL REFERENCES titles(id) ON DELETE RESTRICT,
    watch_space_id UUID NOT NULL,
    watched_seconds INTEGER NOT NULL DEFAULT 0 CHECK (watched_seconds >= 0),  -- union of played content ranges
    completed BOOLEAN NOT NULL DEFAULT FALSE,                                 -- coverage >= configured threshold
    derived_through_sequence BIGINT NOT NULL DEFAULT 0 CHECK (derived_through_sequence >= 0),
    is_final BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, watch_space_id),
    FOREIGN KEY (watch_space_id, title_id)
        REFERENCES watch_spaces(id, title_id) ON DELETE RESTRICT
);
CREATE INDEX ix_title_interactions_user_time ON title_interactions(user_id, updated_at DESC);
CREATE INDEX ix_title_interactions_title_user ON title_interactions(title_id, user_id);

-- Explicit user ratings, independent of any room (finding C6).
CREATE TABLE title_ratings (
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    title_id UUID NOT NULL REFERENCES titles(id) ON DELETE RESTRICT,
    rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, title_id)
);
CREATE INDEX ix_title_ratings_title ON title_ratings(title_id, rating);


-- -------------------------------------------------------------------------------------
-- Session analytics snapshot (module: analytics). Derived from room_events only.
-- -------------------------------------------------------------------------------------

CREATE TABLE watch_space_analytics (
    watch_space_id UUID PRIMARY KEY REFERENCES watch_spaces(id) ON DELETE RESTRICT,
    duration_seconds INTEGER NOT NULL DEFAULT 0 CHECK (duration_seconds >= 0),
    peak_concurrent_participants INTEGER NOT NULL DEFAULT 0 CHECK (peak_concurrent_participants >= 0),
    ai_question_count INTEGER NOT NULL DEFAULT 0 CHECK (ai_question_count >= 0),
    trivia_card_count INTEGER NOT NULL DEFAULT 0 CHECK (trivia_card_count >= 0),
    chat_message_count INTEGER NOT NULL DEFAULT 0 CHECK (chat_message_count >= 0),
    source_last_sequence BIGINT NOT NULL DEFAULT 0 CHECK (source_last_sequence >= 0),
    calculated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- =====================================================================================
-- Rules enforced by the application (cannot be expressed as simple constraints)
-- =====================================================================================
-- R1  Timeline validation (before VALID): schemaVersion supported; document titleId equals the
--     URL title; document durationMs equals titles.duration_ms; 0 <= startMs <= endMs <= duration;
--     unique eventKey; type-specific required payload fields; plain-text strings only; each
--     VARIATION_POINT has >= 2 approved options and exactly one default; option types match the
--     point's variationType; SUBTITLE_TEXT points carry payload.cueKey that exists in the ACTIVE
--     track of titles.default_locale; option locales are valid BCP 47 tags.
-- R2  timeline_events / variation_options are materialized only for VALID versions and are
--     never updated afterwards. Publishing (DRAFT -> CURRENT, previous CURRENT -> SUPERSEDED)
--     happens in one transaction.
-- R3  watch_spaces.pinned_timeline_version_id and room_subtitle_tracks are written once, in
--     the ROOM_STARTED transaction, and never changed.
-- R4  room_votes.timeline_event_id is a VARIATION_POINT; ballots and selections reference
--     approved options only; no vote may be opened for a point already in
--     room_variation_applications.
-- R5  ai_pinned_facts of type AI_ANSWER reference an ANSWERED question; TRIVIA pins reference
--     a TRIVIA event with start_ms <= the room's authoritative position.
-- R6  Room sequence numbers and state_version are assigned only by the per-room mutation
--     lane, guarded by "UPDATE watch_spaces SET last_sequence_no = :new ... WHERE id = :id
--     AND last_sequence_no = :expected". A zero-row update aborts the transaction and forces
--     the lane to re-hydrate. Never compute MAX(sequence_no) + 1 per mutation.
-- R7  chat_messages.room_event_id must reference a CHAT_MESSAGE_POSTED (CHAT),
--     AI_QUESTION_CREATED (AI_QUESTION) or AI_ANSWER_PUBLISHED (AI_ANSWER) event of the same room.
-- R8  Joins check watch_space_moderation.removed_at IS NULL, capacity, lock (new users only)
--     and privacy inside the lane transaction, with SELECT ... FOR UPDATE on the watch_spaces row.
-- R9  Canonical instants (v0.3): watch_spaces.started_at = occurred_at of ROOM_STARTED and
--     watch_spaces.ended_at = occurred_at of ROOM_ENDED for the same room; membership joined_at /
--     left_at equal the occurred_at of their ledger events. ROOM_ENDED is the room's last event:
--     no room_events row may have a sequence_no greater than the ROOM_ENDED row.
-- R10 Refresh-token replay (v0.3): the REUSE_DETECTED family revocation is committed before the
--     API returns 401 REFRESH_TOKEN_REUSED (the service returns an outcome; it does not throw).
-- R11 SUBTITLE_TRACK_SWAP integrity (v0.4): variation_options.subtitle_track_id must reference a
--     subtitle_tracks row whose title_id equals the title of the option's timeline event
--     (timeline_events -> title_timeline_versions.title_id). Checked during timeline validation
--     (R1) and again at publish; violations are field-level validation errors. The locale match
--     is enforced by the composite FK (subtitle_track_id, locale). At publish the referenced track
--     must be APPROVED or ACTIVE.
-- R12 Room subtitle pinning (v0.4): the ROOM_STARTED transaction pins, per locale, only the ACTIVE
--     track of the room's own title (title/locale match enforced by the composite FKs; ACTIVE is
--     checked in the same transaction). A SUBTITLE_TRACK_SWAP option is eligible in a room only if
--     its track is the room's pinned track for that locale.
-- R13 Pinned-track durability (v0.4): a track referenced by room_subtitle_tracks of a non-ENDED room
--     is never deleted (RESTRICT FKs), its cues and asset file are immutable once APPROVED (changes
--     create a new version_number), and asset storage never deletes a file referenced by
--     subtitle_tracks. Status may change to ARCHIVED without affecting rooms that pinned it.

-- =====================================================================================
-- Migration slicing (Flyway, versioned; ddl-auto is never used for schema management)
-- =====================================================================================
-- V1  auth/users: app_users, refresh_tokens                                     (M2)
-- V2  catalog/timeline: titles, genres, title_genres, title_timeline_versions,
--     timeline_events, subtitle_tracks, subtitle_cues, variation_options         (M3)
-- V3  watchspace: watch_spaces, room_subtitle_tracks, watch_space_participants,
--     watch_space_moderation, room_events                                       (M4)
-- V4  chat: chat_messages WITHOUT ai_question_id and its CHECK (ai tables not yet present) (Week 2)
-- V5  ai: ai_questions, ai_answer_sources, ai_pinned_facts; ALTER chat_messages ADD
--     ai_question_id + FK + the AI_QUESTION/AI_ANSWER CHECK, reaching the target above (Week 2)
-- V6  variations: room_votes, variation_votes, room_variation_applications      (Week 3)
-- V7  recommendations/analytics: title_interactions, title_ratings,
--     watch_space_analytics                                                     (Week 3)
-- Seed data (sample title, timeline, subtitle tracks, demo users) is loaded by a separate,
-- profile-gated seed step, not by the schema migrations.
